import{_ as a,o as s,c as n,a4 as e}from"./chunks/framework.BRzJ4ijD.js";const g=JSON.parse('{"title":"渐进记号的真实含义","description":"","frontmatter":{},"headers":[],"relativePath":"dsa/algorithms/complexity/notation.md","filePath":"dsa/algorithms/complexity/notation.md","lastUpdated":1788475713000}'),i={name:"dsa/algorithms/complexity/notation.md"};function o(l,t,d,c,r,h){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="渐进记号的真实含义" tabindex="-1">渐进记号的真实含义 <a class="header-anchor" href="#渐进记号的真实含义" aria-label="Permalink to &quot;渐进记号的真实含义&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p><code>O(f(n))</code> 不是&quot;快慢&quot;，是&quot;函数被夹在哪个量级里&quot;;它只告诉我们<strong>当 n 趋于无穷时增长的形状</strong>，不告诉我们任何常数、任何 cache 行为、任何 CPU 流水线效应。所以<strong>只看 O 是工程师的天真阶段</strong>——但同时记住：完全没有 O 的工程化分析也是不可能的。这一章的任务是把这两层同时立起来。</p><h2 id="形式定义" tabindex="-1">形式定义 <a class="header-anchor" href="#形式定义" aria-label="Permalink to &quot;形式定义&quot;">​</a></h2><p>把 <code>f</code> 和 <code>g</code> 都看作 <code>ℕ → ℝ⁺</code>。捕获三种&quot;夹逼&quot;方向：</p><ul><li><code>f = O(g)</code>：存在 <code>c &gt; 0</code> 和 <code>n₀</code> 使得 <code>∀n ≥ n₀</code> 有 <code>f(n) ≤ c · g(n)</code>. 即&quot;<strong>f 的增长不会跑过 g 的某个常数倍</strong>&quot;.</li><li><code>f = Ω(g)</code>：存在 <code>c &gt; 0</code> 和 <code>n₀</code> 使得 <code>∀n ≥ n₀</code> 有 <code>f(n) ≥ c · g(n)</code>. 即&quot;<strong>f 的增长不会慢于 g 的某个常数倍</strong>&quot;.</li><li><code>f = Θ(g)</code>：刚好同时是 O 和 Ω。&quot;两边都被常数夹死&quot;.</li><li><code>f = o(g)</code> / <code>f = ω(g)</code>：严格小、严格大（取极限之比分别为 0 与 ∞）.</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>习惯写法 <code>f = O(g)</code> 里的 <code>=</code> 不对称。<code>O(g)</code> 是一个<strong>函数集合</strong>，严格写法是 <code>f ∈ O(g)</code>. 但业界已经把 <code>{f | f = O(g)}</code> 当成口语化的某个等价集，所以约定俗成就这样了。你读 <code>&quot;T(n) = O(n log n)&quot;</code> 时脑子里要翻译成&quot;T(n) 落在 Θ(n log n) 差不多的量级上&quot;。</p></div><h2 id="工程师对渐进的五层误读" tabindex="-1">工程师对渐进的五层误读 <a class="header-anchor" href="#工程师对渐进的五层误读" aria-label="Permalink to &quot;工程师对渐进的五层误读&quot;">​</a></h2><h3 id="误读-1-o-1-一定比-o-log-n-快" tabindex="-1">误读 1：O(1) 一定比 O(log n) 快 <a class="header-anchor" href="#误读-1-o-1-一定比-o-log-n-快" aria-label="Permalink to &quot;误读 1：O(1) 一定比 O(log n) 快&quot;">​</a></h3><p>错。<code>O(1)</code> 里的常数项决定小规模胜负。例子：哈希单次操作 ≈ 几十到几百条指令（hash、mod、可能的 cache miss、可能的 tombstone 探测）；二分单次 ≈ 10 条指令（一次比较 + 一次地址加法 + 一次 cache hopeful 读）。n &lt; 100 时二分一般是赢的。</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>benchmark 上一个常见的反例：Go map 在 100 个键时比 <code>sort.Search</code> 慢。这就是&quot;O(1)&quot;输给&quot;O(log n)&quot;在工程现场的实证。说明渐进常数大于 10。</p></div><h3 id="误读-2-o-log-n-都是一个量级" tabindex="-1">误读 2：O(log n) 都是一个量级 <a class="header-anchor" href="#误读-2-o-log-n-都是一个量级" aria-label="Permalink to &quot;误读 2：O(log n) 都是一个量级&quot;">​</a></h3><p><code>log</code> 的底是常数差异。<code>log₂ n</code> 与 <code>ln n</code> 差一个 ln 2 ≈ 0.69 的乘性系数。看起来微不足道，但在<strong>每次比较代价高</strong>时：</p><ul><li>二叉树每次比较 1 cycle；</li><li>红黑树 + string key 时每次比较可能上百 cycle（strcmp 遍历整个 key，常常命中 cache 也不好）;</li><li>B+ 树页内比较一次后用 SIMD 8-wide 一次比 8 个 key —— 常数缩小 8 倍.</li></ul><p>到这里你就理解了：<strong>大 O 不区分 log 的底，但工程常数能差 10 倍</strong>.</p><h3 id="误读-3-平均复杂度-期望复杂度" tabindex="-1">误读 3：平均复杂度 = 期望复杂度 <a class="header-anchor" href="#误读-3-平均复杂度-期望复杂度" aria-label="Permalink to &quot;误读 3：平均复杂度 = 期望复杂度&quot;">​</a></h3><p>&quot;平均&quot;必须指明分布。CLRS 上写&quot;平均&quot;默认均匀分布；而<strong>工程平均</strong>常常是&quot;产品实际输入分布下的期望&quot;.</p><ul><li>排序算法的&quot;平均 O(n log n)&quot;指所有排列等可能；</li><li>同样的快排在&quot;已序数据&quot;上能退化到 O(n²)。</li></ul><p>这就是为什么 std::sort 用 introsort（递归深度超过 2 log n 时切到 heap sort），是给&quot;平均分析失效&quot;打的补丁。</p><h3 id="误读-4-o-n-里只有一个常数" tabindex="-1">误读 4：O(n) 里只有一个常数 <a class="header-anchor" href="#误读-4-o-n-里只有一个常数" aria-label="Permalink to &quot;误读 4：O(n) 里只有一个常数&quot;">​</a></h3><p>数字电路视角告诉我们：<code>O(n)</code> 里其实有两次 трагедия：</p><ol><li><strong>每条指令的 throughput 是 1 ns 级别</strong>（约 3 GHz / cycle）。</li><li><strong>每次内存访问的 latency 从 1 ns (L1) 到 80 ns (DRAM)</strong>.</li></ol><p>所以同样 O(n)，cache-friendly 版本能跑出 100 GB/s 的内存带宽；cache-hostile 版本只能跑出 5 GB/s。<strong>差 20 倍</strong>。这就是为什么工程里&quot;常数因子&quot;实际上跨两个数量级是常态。</p><h3 id="误读-5-复杂度能直接指导性能" tabindex="-1">误读 5：复杂度能直接指导性能 <a class="header-anchor" href="#误读-5-复杂度能直接指导性能" aria-label="Permalink to &quot;误读 5：复杂度能直接指导性能&quot;">​</a></h3><p>不能。O 给的是形状，性能还要看：</p><ul><li>常数；</li><li>cache-locality；</li><li>分支预测准确率（分支错误一次流水线 flush 浪费 ~15 cycle）；</li><li>SIMD vectorization（紧邻操作可向量化时跑 4-wide/8-wide）；</li><li>TLB 命中（4K page 对 1 GB 数据需要 256K TLB 项，远超 TLB 大小）；</li><li>NUMA（跨 socket 访问再加 100+ ns）。</li></ul><p>下面我们把这些点逐层揭示——它们各自都是计算机科学的&quot;硬&quot;层级，<strong>复杂度只是这一切的抽象外壳</strong>.</p><h2 id="主定理-分治复杂度从哪儿来" tabindex="-1">主定理：分治复杂度从哪儿来 <a class="header-anchor" href="#主定理-分治复杂度从哪儿来" aria-label="Permalink to &quot;主定理：分治复杂度从哪儿来&quot;">​</a></h2><p><code>T(n) = a · T(n/b) + f(n)</code> 的三条规则，背后是<strong>比较 f 与 <code>n^(log_b a)</code> 哪个主导</strong>：</p><table tabindex="0"><thead><tr><th>情形</th><th>条件</th><th>结论</th></tr></thead><tbody><tr><td>1</td><td><code>f = O(n^(log_b a − ε))</code></td><td><code>T = Θ(n^(log_b a))</code></td></tr><tr><td>2</td><td><code>f = Θ(n^(log_b a · log^k n))</code></td><td><code>T = Θ(n^(log_b a · log^(k+1) n))</code></td></tr><tr><td>3</td><td><code>f = Ω(n^(log_b a + ε))</code> 且 regular</td><td><code>T = Θ(f(n))</code></td></tr></tbody></table><p>直觉：<strong>两个 &quot;工程贡献&quot;——递归子树数量 a 与每个分裂的合并工作 f——哪个增长更快，就是 T 的主导</strong>.</p><table tabindex="0"><thead><tr><th>场景</th><th>a</th><th>b</th><th>f(n)</th><th>T(n)</th></tr></thead><tbody><tr><td>二分查找</td><td>1</td><td>2</td><td>O(1)</td><td>Θ(log n)</td></tr><tr><td>归并排序</td><td>2</td><td>2</td><td>O(n)</td><td>Θ(n log n)</td></tr><tr><td>Strassen 矩阵乘法</td><td>7</td><td>2</td><td>O(n²)</td><td>Θ(n^log₂7) ≈ Θ(n^2.807)</td></tr><tr><td>Karatsuba 大整数乘</td><td>3</td><td>2</td><td>O(n)</td><td>Θ(n^log₂3) ≈ Θ(n^1.585)</td></tr><tr><td>普通斐波那契递归</td><td>2</td><td>1</td><td>O(1)</td><td>Θ(2^n)（不在主定理范围，但用同一思路）</td></tr></tbody></table><p>主定理的工程隐藏点：<strong>它忽略常数</strong>。Strassen 在 n &lt; 100 常输给朴素乘法，原因就是常数 7 比 8 大，但每层多做很多加法和地址跳。</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>这就是为什么平均 O(n^2.807) 的 Strassen 直到 n ≈ 1000 才稳定赢过 O(n^3) 朴素。<strong>当 n 还在 cache 里时，cache-friendly 的朴素矩阵乘能跑到 30+ GFLOPS</strong>，而 Strassen 的间接内存 pattern 跑不到 10 GFLOPS。CPU 通用核心的算力差距被掩盖在大 O 里。</p></div><h2 id="从-o-到运行时间的链路" tabindex="-1">从 O 到运行时间的链路 <a class="header-anchor" href="#从-o-到运行时间的链路" aria-label="Permalink to &quot;从 O 到运行时间的链路&quot;">​</a></h2><p>让我们把&quot;复杂度&quot;和&quot;真实运行时间&quot;的链路逐层补完。以一次 <code>for (i=0; i&lt;n; i++) sum += a[i];</code> 为例。</p><h3 id="_1-复杂度层-o-n" tabindex="-1">1. 复杂度层：O(n) <a class="header-anchor" href="#_1-复杂度层-o-n" aria-label="Permalink to &quot;1. 复杂度层：O(n)&quot;">​</a></h3><p>这是抽象最高层。我们只说访问模式线性增长。</p><h3 id="_2-指令数层-约-4n-条指令" tabindex="-1">2. 指令数层：约 4n 条指令 <a class="header-anchor" href="#_2-指令数层-约-4n-条指令" aria-label="Permalink to &quot;2. 指令数层：约 4n 条指令&quot;">​</a></h3><p>x86 汇编大致：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov  rax, [a]             ; 取数组基地址</span></span>
<span class="line"><span>xor  ecx, ecx             ; sum = 0</span></span>
<span class="line"><span>loop:</span></span>
<span class="line"><span>    mov  edx, [rax + 4*i] ; 一次 load</span></span>
<span class="line"><span>    add  ecx, edx         ; 加到 sum</span></span>
<span class="line"><span>    inc  i                ; i++</span></span>
<span class="line"><span>    cmp  i, n</span></span>
<span class="line"><span>    jb   loop</span></span></code></pre></div><p>四条指令，每轮迭代都要跑一次。所以总开销约 <code>4n</code> 条指令。</p><h3 id="_3-指令-throughput-层-约-1-ns-iter" tabindex="-1">3. 指令 throughput 层：约 1 ns / iter <a class="header-anchor" href="#_3-指令-throughput-层-约-1-ns-iter" aria-label="Permalink to &quot;3. 指令 throughput 层：约 1 ns / iter&quot;">​</a></h3><p>现代 CPU 每条简单整数 ALU 指令 throughput ≈ 0.25～0.5 cycle。但内存 load 在 cache hit 时 latency 仍 ~4 cycle (L1)，hit rate 100% 时通过流水线可以&quot;叠&quot;到每 cycle 一条 load。所以每个循环迭代大约 1 cycle = 0.33 ns（按 3 GHz）.</p><p>总时间：~ n ns. 一个 10^8 个 int 的求和：~ 100 ms.</p><h3 id="_4-cache-tlb-层-内存层级拉宽到-80-ns" tabindex="-1">4. cache / TLB 层：内存层级拉宽到 80 ns <a class="header-anchor" href="#_4-cache-tlb-层-内存层级拉宽到-80-ns" aria-label="Permalink to &quot;4. cache / TLB 层：内存层级拉宽到 80 ns&quot;">​</a></h3><p>CPU cache 是金字塔：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>register   ≈ 0 cycle       (1-2 ns as architecture)</span></span>
<span class="line"><span>L1 (32KB)  ≈ 4 cycle       (~1 ns)</span></span>
<span class="line"><span>L2 (256KB) ≈ 12 cycle      (~4 ns)</span></span>
<span class="line"><span>L3 (8MB)   ≈ 40 cycle      (~12 ns)</span></span>
<span class="line"><span>DRAM       ≈ 200 cycle      (~80 ns)</span></span></code></pre></div><p>如果数组远超 L3 —— 10^8 int = 400 MB —— 那么 load 几乎都命中 DRAM，每次 wait 80 ns 即 200 cycle。CPU 的 prefetcher 会主动找出连续模式提前加载到 cache line 64 字节，<strong>让一次 80 ns 的 DRAM access 满载 16 个 int 加法</strong>. 加上 SIMD 一次加 4-8 个 int：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// AVX2 一次加 8 个 int32</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">__m256i vsum </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> _mm256_setzero_si256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> n; i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    __m256i v </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> _mm256_loadu_si256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((__m256i</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[i]);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    vsum </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> _mm256_add_epi32</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(vsum, v);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>效果：~3 cycle per 8 个 int，折合每元素 1 ns 的 <strong>1/15</strong>：8 GB/s 顺序流可到 100+ GB/s。</p><p>到这里你应该看见：<strong>O(n) 在不同层之下能差 100 倍，但它们都叫 O(n)</strong>.</p><h3 id="_5-数字电路层-cache-line-为什么是-64-字节" tabindex="-1">5. 数字电路层：cache line 为什么是 64 字节 <a class="header-anchor" href="#_5-数字电路层-cache-line-为什么是-64-字节" aria-label="Permalink to &quot;5. 数字电路层：cache line 为什么是 64 字节&quot;">​</a></h3><p>为什么是 64 字节而不是 32 或 128？</p><ul><li>一行读出要并行传输给 L1：64 字节正好是 DDR 一条 burst length (8 × 8 字节 = 64)；</li><li>L1 的 ECC、tag 位、一致性管理都按行做，64 字节让 L1 + L2 + L3 行号对齐，<strong>简化了一致协议 (MESI/MOESI)</strong>；</li><li>主板上 64 字节也对应 PCIe 一次 TLP payload 上限（Completer 上限典型 128B/256B，但 cache line 仍是 64B）。</li></ul><p>所以&quot;64&quot;不是任意数字，是<strong>DRAM burst 与 cache 一致协议共同压制的结果</strong>。这就是&quot;知其所以然&quot;的底层：连 64 这个常数都是数字电路决定的。</p><h3 id="_6-fpga-视角-bram-srl-分布式-ram-是另一套" tabindex="-1">6. FPGA 视角：BRAM/SRL/分布式 RAM 是另一套 <a class="header-anchor" href="#_6-fpga-视角-bram-srl-分布式-ram-是另一套" aria-label="Permalink to &quot;6. FPGA 视角：BRAM/SRL/分布式 RAM 是另一套&quot;">​</a></h3><p>FPGA 不是 CPU 上的 cache 模型。Altra/Xilinx FPGA 里有：</p><ul><li><strong>Distributed RAM</strong>（每个 LUT 都能当 64 bit RAM）—— 极快，几十 ps；</li><li><strong>URAM / BRAM</strong>：块 RAM，&gt;1 Mbit，~1-2 cycle；</li><li><strong>HBM</strong>：3D 堆叠 DRAM，~30-100 GB/s/channel，~ 80 ns latency。</li></ul><p>FPGA 上的算法设计常常把一个图处理算法<strong>展开成 pipeline</strong>：每个 cycle 进一个 vertex、出一个 vertex，让所有计算在几百 MHz 频率下展开运行，而不是&quot;O(n) 循环&quot;. 这就是把 O(n) 工程化到硬件层。</p><p>你看，<strong>同一个 O(n) 的求和，从软件常数 3 到数字电路常数 1/15 再到 FPGA 的 &quot;1 cycle/element&quot;</strong>——每一层都有它自己的常数。</p><h2 id="主导项之外的相加规则" tabindex="-1">主导项之外的相加规则 <a class="header-anchor" href="#主导项之外的相加规则" aria-label="Permalink to &quot;主导项之外的相加规则&quot;">​</a></h2><p>一句话：<strong>相加取最坏，相乘入相邻</strong>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>O(f) + O(g) = O(max(f, g))     # 比如 O(n log n) + O(n) = O(n log n)</span></span>
<span class="line"><span>O(f) × O(g) = O(f × g)         # 嵌套循环 O(n × m)</span></span>
<span class="line"><span>O(f) + o(f) = O(f)             # 低阶项被吞噬</span></span></code></pre></div><p>但有边界陷阱：</p><ul><li><code>T(n) = T(n-1) + n</code> 不是 <code>O(n)</code> 而是 <code>O(n²)</code> —— 是等差级数累计的闭式，<strong>不是简单相加</strong>.</li><li><code>T(n) = T(n-1) + 2T(n/2) + n</code> —— 退化递归；先画递归树数工作总量，不要直接进主定理。</li><li><code>T(n) = 2T(n/2) + n/log n</code> —— 主定理 case 2 的&quot;烦人角落&quot;（Akra-Bazzi 才稳）；结论是 <code>Θ(n log log n)</code>。</li></ul><p>工程里写递归/分治之前，<strong>至少画一次递归树画三行</strong>，避免被主定理的形式骗到。</p><h2 id="速查表-含工程常数注释" tabindex="-1">速查表（含工程常数注释） <a class="header-anchor" href="#速查表-含工程常数注释" aria-label="Permalink to &quot;速查表（含工程常数注释）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>渐进</th><th>实际 ops @ n=10⁶</th><th>工程注释</th></tr></thead><tbody><tr><td>O(1)</td><td>几 ns</td><td>哈希、寻址、SIMD 单向</td></tr><tr><td>O(log n)</td><td>~20 次比较</td><td>树、堆、二分；热区一般 ~10 ns</td></tr><tr><td>O(n)</td><td>~10⁶ ops</td><td>cache 友好 ~3 ms；cache hostile ~50 ms</td></tr><tr><td>O(n log n)</td><td>~2×10⁷ ops</td><td>排序门限；32 MB 数据 ~100 ms</td></tr><tr><td>O(n²)</td><td>10¹² ops</td><td>n=10⁶ 必死；n=10⁴ 约 100 ms</td></tr><tr><td>O(2ⁿ)</td><td>不可行</td><td>n≤30 才能跑</td></tr></tbody></table><h2 id="这一章带走的东西" tabindex="-1">这一章带走的东西 <a class="header-anchor" href="#这一章带走的东西" aria-label="Permalink to &quot;这一章带走的东西&quot;">​</a></h2><ul><li>O / Ω / Θ 是夹逼式的，<code>=</code> 是个误用符号；</li><li>O 的工程常数能跨两个数量级，因为 cache + 流水线 + SIMD 三者各贡献一个&quot;乘性加速&quot;；</li><li>O(log n) 在工程里和底不同（B+ 树页内 SIMD 比一次对 8 个 key —— &quot;log 底 8&quot;）；</li><li>主定理忽略常数，Strassen 在 cache 内打不过朴素乘法是&quot;O 不够看&quot;的最典型案例；</li><li>一行 <code>O(n)</code> 求和从顶层 software 常数 3 一路到 FPGA 1 cycle/element，每一层都是一层硬件知识.</li></ul><p>下一节 → <a href="./amortized">摊还分析入门</a>：把&quot;序列总和&quot;的渐进分析框入工程可证的形式。</p>`,72)])])}const u=a(i,[["render",o]]);export{g as __pageData,u as default};
